import { existsSync, readFileSync, writeFileSync, readdirSync } from "node:fs";

type ContrastRecord = {
  ratio: number | null;
  threshold: number;
  element: string;
  kind?: string;
  text?: string;
  foreground: string;
  background: number[];
  opacity?: number;
  gradientSamples?: number;
};
type OptionalAlias = { name: string; selector: string; hasFallback?: boolean };
type Audit = {
  theme: string;
  route: string;
  state: string;
  width?: number;
  records?: ContrastRecord[];
  axe?: Record<string, unknown>[];
  missing?: unknown[];
  neutral?: unknown[];
  unresolved?: OptionalAlias[];
  layout?: { horizontalOverflow: number };
};
type Totals = {
  pageStates: number;
  measured: number;
  failures: number;
  incomplete: number;
  axeViolations: number;
  missingPrimitives: number;
  neutralFailures: number;
  layoutFailures: number;
};
// Regenerable measurement dumps stay beside other ignored test output.
const directory = "test-results/theme-audit";
const manualFindingsPath = "docs/theme-audit/manual-findings.json";
if (!existsSync(`${directory}/artifacts`)) {
  throw new Error(
    "Run npm run test:themes before generating the detailed report.",
  );
}
const files = readdirSync(`${directory}/artifacts`).filter((name) =>
  name.endsWith(".json"),
);
const audits: Audit[] = files.flatMap((file) =>
  JSON.parse(readFileSync(`${directory}/artifacts/${file}`, "utf8")),
);
const csv = (rows: unknown[][]) =>
  rows
    .map((row) =>
      row
        .map((value) => `"${String(value ?? "").replaceAll('"', '""')}"`)
        .join(","),
    )
    .join("\n") + "\n";
const contrast: unknown[][] = [
  [
    "theme",
    "page",
    "state",
    "width",
    "element",
    "kind",
    "text",
    "foreground",
    "background",
    "opacity",
    "ratio",
    "threshold",
    "result",
    "gradientSamples",
  ],
];
const findings: Record<string, unknown>[] = JSON.parse(
  readFileSync(manualFindingsPath, "utf8"),
);
const summary: Record<string, Totals> = {};
for (const audit of audits) {
  const totals = (summary[audit.theme] ??= {
    pageStates: 0,
    measured: 0,
    failures: 0,
    incomplete: 0,
    axeViolations: 0,
    missingPrimitives: 0,
    neutralFailures: 0,
    layoutFailures: 0,
  });
  totals.pageStates++;
  if ((audit.layout?.horizontalOverflow ?? 0) > 1) {
    totals.layoutFailures++;
    findings.push({
      theme: audit.theme,
      page: audit.route,
      state: audit.state,
      failure: "layout: document horizontal overflow",
      ...audit.layout,
    });
  }
  for (const record of audit.records ?? []) {
    const result =
      record.ratio === null
        ? "INCOMPLETE"
        : record.ratio + 0.000001 < record.threshold
          ? "FAIL"
          : "PASS";
    contrast.push([
      audit.theme,
      audit.route,
      audit.state,
      audit.width ?? 1440,
      record.element,
      record.kind ?? "text",
      record.text,
      record.foreground,
      JSON.stringify(record.background),
      record.opacity ?? 1,
      record.ratio,
      record.threshold,
      result,
      record.gradientSamples ?? 1,
    ]);
    if (result === "INCOMPLETE") totals.incomplete++;
    else {
      totals.measured++;
      if (result === "FAIL") totals.failures++;
    }
    if (result !== "PASS")
      findings.push({
        theme: audit.theme,
        page: audit.route,
        state: audit.state,
        failure: "contrast",
        ...record,
        result,
      });
  }
  totals.axeViolations += (audit.axe ?? []).length;
  totals.missingPrimitives += (audit.missing ?? []).length;
  totals.neutralFailures += (audit.neutral ?? []).length;
  for (const violation of audit.axe ?? [])
    findings.push({
      theme: audit.theme,
      page: audit.route,
      state: audit.state,
      failure: "axe",
      ...violation,
    });
}
const optional: Record<string, OptionalAlias & { scopes: Set<string> }> = {};
for (const audit of audits)
  for (const entry of audit.unresolved ?? []) {
    if (
      /^--(?:tw-|default-)/.test(entry.name) ||
      /radius|duration|height|font/.test(entry.name)
    )
      continue;
    const key = `${entry.name} | ${entry.selector}`;
    const item = (optional[key] ??= { ...entry, scopes: new Set() });
    item.scopes.add(`${audit.theme}/${audit.route}/${audit.state}`);
  }
writeFileSync(`${directory}/contrast.csv`, csv(contrast));
writeFileSync(
  `${directory}/findings.json`,
  JSON.stringify(findings, null, 2) + "\n",
);
writeFileSync(
  `${directory}/summary.json`,
  JSON.stringify(summary, null, 2) + "\n",
);
writeFileSync(
  `${directory}/optional-aliases.json`,
  JSON.stringify(
    Object.values(optional).map((item) => ({
      ...item,
      scopes: [...item.scopes],
    })),
    null,
    2,
  ) + "\n",
);
const rows = [
  "| Theme | States | Measured pairs | Fail | Unmeasured | Axe violations | Missing primitives | Neutral failures | Screen overflow |",
  "| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
];
for (const [theme, totals] of Object.entries(summary))
  rows.push(`| ${theme} | ${Object.values(totals).join(" | ")} |`);
rows.push(
  "",
  "Print-layout findings are separate from the screen-overflow column. Actual 200% browser zoom and native Windows controls/print dialogs remain unverified.",
  "",
  "| Theme | Measured colors | Axe | Screen overflow | Overall requested audit |",
  "| --- | --- | --- | --- | --- |",
);
const manual = JSON.parse(readFileSync(manualFindingsPath, "utf8")) as Array<{
  theme: string;
}>;
for (const [theme, totals] of Object.entries(summary)) {
  const color =
    totals.failures || totals.missingPrimitives || totals.neutralFailures
      ? "FAIL"
      : totals.incomplete
        ? "INCOMPLETE"
        : "PASS";
  const printFailure = manual.some((finding) =>
    theme.startsWith(finding.theme),
  );
  rows.push(
    `| ${theme} | ${color} | ${totals.axeViolations ? "FAIL" : "PASS"} | ${totals.layoutFailures ? "FAIL" : "PASS"} | ${totals.axeViolations || printFailure ? `FAIL: ${totals.axeViolations ? "toast landmark semantics" : ""}${totals.axeViolations && printFailure ? "; " : ""}${printFailure ? "layout findings" : ""}; native checks incomplete` : "INCOMPLETE: native checks and full manual print review"} |`,
  );
}
writeFileSync(`${directory}/results.md`, rows.join("\n") + "\n");
console.log(JSON.stringify(summary, null, 2));
